TreeNode* buildBT(std::vector<int>& inorder, std::vector<int>& postorder,
                  int inStart, int inEnd, int postStart, int postEnd) {
    // Build a hash map from node value to its index in the inorder traversal.
    // The map is constructed only once for the whole tree reconstruction.
    static std::unordered_map<int, int> indexMap;
    // Re‑build the map if it is empty or does not correspond to the current input vectors.
    if (indexMap.empty() || static_cast<int>(indexMap.size()) != static_cast<int>(inorder.size())) {
        indexMap.clear();
        for (int i = 0; i < static_cast<int>(inorder.size()); ++i) {
            indexMap[inorder[i]] = i;
        }
    }

    // Base case: no elements to process.
    if (inStart > inEnd) {
        return nullptr;
    }

    // The last element in the current postorder segment is the root.
    TreeNode* root = new TreeNode(postorder[postEnd]);
    int rootIdx = indexMap[root->val];   // O(1) lookup instead of linear scan.

    int leftSize  = rootIdx - inStart;   // Number of nodes in the left subtree.
    int rightSize = inEnd - rootIdx;     // Number of nodes in the right subtree.

    // Recursively build left and right subtrees using the computed sizes.
    root->left = buildBT(inorder, postorder,
                         inStart, rootIdx - 1,
                         postStart, postStart + leftSize - 1);
    root->right = buildBT(inorder, postorder,
                          rootIdx + 1, inEnd,
                          postEnd - rightSize, postEnd - 1);

    return root;
}

