using std::vector;
using std::string;
using std::unordered_map;

// Recursive solution with memoisation to avoid recomputing the same sub‑expressions.
vector<int> solve(string s) {
    // Cache that maps a sub‑expression (as a string) to all possible evaluation results.
    // Declared static so that the same cache is reused across recursive calls.
    static unordered_map<string, vector<int>> memo;

    // If we have already solved this sub‑expression, return the cached result.
    auto it = memo.find(s);
    if (it != memo.end()) {
        return it->second;
    }

    vector<int> result;

    // Try every operator position as a split point.
    for (size_t i = 0; i < s.length(); ++i) {
        char op = s[i];
        if (op == '+' || op == '-' || op == '*') {
            // Recursively compute results for the left and right sub‑expressions.
            vector<int> left_results  = solve(s.substr(0, i));
            vector<int> right_results = solve(s.substr(i + 1));

            // Combine each pair of left/right results using the current operator.
            for (int x : left_results) {
                for (int y : right_results) {
                    if (op == '+') {
                        result.push_back(x + y);
                    } else if (op == '-') {
                        result.push_back(x - y);
                    } else { // op == '*'
                        result.push_back(x * y);
                    }
                }
            }
        }
    }

    // Base case: the substring contains only a number.
    if (result.empty()) {
        result.push_back(std::stoi(s));
    }

    // Store the computed result in the memo table before returning.
    memo[s] = result;
    return result;
}
