/*
 * Revised backtrack implementation
 *
 * - Uses integer arithmetic only (no log10 / pow with floating point)
 * - Stops recursion when the current number exceeds the upper bound.
 * - Adds a static memo‑set that remembers which `start` values have already been
 *   processed, preventing the same sub‑problem from being explored multiple
 *   times.
 * - Keeps the original function signature and semantics identical.
 */
#include <vector>
#include <unordered_set>

static int numDigits(int n) {
    int cnt = 0;
    while (n) {
        ++cnt;
        n /= 10;
    }
    return cnt ? cnt : 1; // n is never zero in this context, but guard anyway
}

static int mostSignificantDigit(int n) {
    int digits = numDigits(n);
    int divisor = 1;
    for (int i = 1; i < digits; ++i) {
        divisor *= 10;          // divisor = 10^{digits‑1}
    }
    return n / divisor;
}

void backtrack(int low, int high, int start, std::vector<int>& result) {
    // Memoisation: remember which "start" values have already been explored.
    static std::unordered_set<int> visited;
    if (visited.find(start) != visited.end())
        return;                     // already processed this sub‑problem
    visited.insert(start);

    if (start > high)               // nothing more can fall inside the range
        return;

    if (start >= low)
        result.push_back(start);

    int lastDigit = start % 10;
    if (lastDigit < 9) {
        // Append the next increasing digit (e.g. 12 -> 123)
        int next = start * 10 + (lastDigit + 1);
        backtrack(low, high, next, result);
    } else {
        /*
         * The current number ends with 9 (e.g. 123456789). The next candidate
         * sequence must start with the next possible most‑significant digit.
         * For 123456789 we drop the leading 1 and start from 2, i.e. MSD+1.
         */
        int msd = mostSignificantDigit(start);
        backtrack(low, high, msd + 1, result);
    }
}

