#include <vector>
#include <unordered_map>
using namespace std;

// Helper to create a unique key from (idx, prev).
// We offset prev by 1 so that the sentinel value -1 maps to 0.
static inline long long make_key(int idx, int prev) {
    return (static_cast<long long>(idx) << 32) ^ static_cast<unsigned int>(prev + 1);
}

/*
 *  generate – finds the longest subsequence (stored in *result*) of *nums*
 *  such that each element is divisible by the element that precedes it.
 *
 *  The original implementation explored the whole recursion tree each time,
 *  leading to exponential work because many sub‑problems (identified by the
 *  pair (idx, prev)) are visited repeatedly.  The version below memoises the
 *  best subsequence for every distinct state, guaranteeing that each sub‑problem
 *  is solved exactly once.
 *
 *  The public signature is unchanged – the function still returns nothing and
 *  updates *result* via reference.  Internally a static unordered_map is used as
 *  a cache; the map is sized automatically from the arguments, not from a fixed
 *  constant.
 */
void generate(int idx,
              const vector<int>& nums,
              vector<int>& result,
              vector<int>& temp,
              int prev) {
    // The memoisation table maps a state (idx, prev) to the best subsequence
    // achievable from that state.
    static unordered_map<long long, vector<int>> memo;

    // Base case – we have considered all elements.
    if (idx >= static_cast<int>(nums.size())) {
        if (temp.size() > result.size()) {
            result = temp;                 // update the global best
        }
        return;
    }

    long long key = make_key(idx, prev);
    auto cached = memo.find(key);
    if (cached != memo.end()) {
        // We already know the optimal subsequence from this state.
        const vector<int>& bestFromHere = cached->second;
        // If it improves the overall result, propagate it.
        if (bestFromHere.size() > result.size()) {
            result = bestFromHere;
        }
        return;
    }

    // ---------------------------------------------------------------------
    // 1) Try to take nums[idx] (only if it satisfies the divisibility rule).
    // ---------------------------------------------------------------------
    vector<int> bestOverall = result; // will hold the best subsequence for this state
    if (prev == -1 || nums[idx] % prev == 0) {
        temp.push_back(nums[idx]);
        generate(idx + 1, nums, result, temp, nums[idx]);
        // After the recursive call, *result* may have been updated to the best
        // sequence that includes nums[idx].  Capture that candidate.
        if (result.size() > bestOverall.size()) {
            bestOverall = result;
        }
        temp.pop_back(); // backtrack for the next alternative
    }

    // ---------------------------------------------------------------------
    // 2) Skip nums[idx] and continue.
    // ---------------------------------------------------------------------
    // Preserve *result* (which currently holds the best after the "take" branch)
    // before exploring the "skip" branch, because the skip branch must start
    // from the same global best.
    vector<int> resultBeforeSkip = result;
    generate(idx + 1, nums, result, temp, prev);
    if (result.size() > bestOverall.size()) {
        bestOverall = result;
    }
    // Restore the global best to the best found in either branch before we
    // store it in the memo table.
    result = bestOverall;

    // Store the optimal subsequence for this state.
    memo.emplace(key, bestOverall);
}
