        std::size_t operator()(std::uint64_t k) const noexcept {
            // Simple identity hash is sufficient for 64‑bit keys.
            return static_cast<std::size_t>(k);
        }
    };
    static std::unordered_map<std::uint64_t, int, KeyHash> memo;

    // Base case – we have examined all elements.
    if (i >= static_cast<int>(nums.size())) {
        return 0;
    }

    // Build the cache key for the current state.
    std::uint64_t key = static_cast<std::uint64_t>(i) << 33;                     // i part
    key |= static_cast<std::uint64_t>(prev + 1) << 1;                           // prev+1 part
    key |= static_cast<std::uint64_t>(mod & 1);                                 // mod part

    // Return cached result if it exists.
    auto it = memo.find(key);
    if (it != memo.end()) {
        return it->second;
    }

    // ---------------------------------------------------------------------
    //  Recursive exploration: either take the current element (if it fits)
    //  or skip it. The definition of "fits" follows the original code.
    // ---------------------------------------------------------------------
    int take = 0;
    if (prev == -1 || ((nums[prev] + nums[i]) % 2) == mod) {
        take = 1 + LIS(nums, i + 1, i, mod);
    }
    int skip = LIS(nums, i + 1, prev, mod);

    int best = std::max(take, skip);
    memo[key] = best;            // store for future calls
    return best;
